#include <stdio.h>
#define MAX 1000
int main(void) {
    int st[MAX], top = 0, x;
    while (scanf("%d", &x) == 1 && x != 0) st[top++] = x;
    for (int i = top - 1; i >= 0; i--) {
        printf("%d", st[i]);
        if (i > 0) printf(" ");
    }
    printf("\n");
    return 0;
}
